head.script:
scwin.screenId = "uldmgt50317";

///////// 1. 변수 및 선언 영역 /////////

scwin.frame = undefined;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "img_9", attr: "src", fn: function () { return "/img/filing/body/pop_title_3" + String(((String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("mode"))) === "create") ? "0" : "1")) + ".gif"; } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_lawItmBystepAddNo", fn: function(){ return ((dlt_detailLawItems.getCellData(0, "lawItmBystepAddNo") ?? (() => { throw new Error("unresolved:" + "detailLawItem.lawItmBystepAddNo"); })()) > 1); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_39", entity: "dlt_detailLawItems", countIds: [], cells: [{ childId: "option_43", fn: function (v, i) { return String(v("lawItmSeq")); } }, { childId: "__rc1", fn: function (v, i) { return String(i + 1) + " " + String(v("lawItmTitle")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_editForm = { action: "", method: 'post', target: '' };

scwin.obj = undefined; try { scwin.obj = /* sdd-asis-lifecycle:begin obj — as-is 원문 본문(전환 이관 · 포팅 적용됨) */opener.Potential.Provider/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50317' }); }

scwin.frameId = undefined; try { scwin.frameId = /* sdd-asis-lifecycle:begin frameId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.obj.ActiveFrame.FrameID/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'uldmgt50317' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_attrReals();
        await scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50317.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.img_58_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_58_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_58_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.insert()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50317.img_58_onclick' }); }
};

/**
 * @event
 * @name scwin.img_59_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_59_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_59_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.close()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50317.img_59_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Insert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Insert = async function () {
    const sbmOptions = {
        id: "tx_fn_Insert",
        method: "post",
        action: "/filing/updateOnlineDisclosureLawDetail.do",
        ref: "dma_InsertReq",
        target: "dlt_detailLawItems=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50317.tx_fn_Insert" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/filing/updateOnlineDisclosureLawDetail.do?method=prepareUpdateDisclosureLawByitemDetailedRule&mode=create",
        ref: "dma_loadListReq",
        target: "dlt_detailLawItems=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50317.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.insert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.insert = async function () {
    /* sdd-asis-lifecycle:begin fn_Insert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_InsertReq').set('method', "updateDisclosureLawByitemDetailedRule");
    scwin.form_editForm.action = "/filing/updateOnlineDisclosureLawDetail.do";
    await scwin.tx_fn_Insert();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.close
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.close = function () {
    /* sdd-asis-lifecycle:begin fn_Close — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
